const axios = require('axios')
const cheerio = require('cheerio')

const BASE = 'https://ww3.lectulandia.co'
const UA = 'Mozilla/5.0 (Linux; Android 11; Redmi Note 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36'

const client = axios.create({
  headers: {
    'User-Agent': UA,
    'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
    'Accept-Language': 'es-ES,es;q=0.9',
    'Accept-Encoding': 'gzip, deflate, br',
    'Connection': 'keep-alive'
  },
  timeout: 12000,
  maxRedirects: 5
})

const toAbsolute = (url) => {
  if (!url) return null
  return url.startsWith('http') ? url : BASE + url
}

const clean = (text) => {
  return text?.replace(/\s+/g, ' ').trim() || ''
}

const safe = async (fn) => {
  try {
    return await fn()
  } catch (e) {
    return null
  }
}

//-----
async function resolveAntUpload(url) {
  if (!url || !url.includes('antupload.com')) return null

  try {
    const res = await client.get(url)

    const cookies = res.headers['set-cookie']
      ?.map(c => c.split(';')[0])
      .join('; ') || ''

    const $ = cheerio.load(res.data)

    const finalHref =
      $('#downloadB').attr('href') ||
      $('a[href*="/filed/"]').first().attr('href')

    if (!finalHref) return null

    const absolute = finalHref.startsWith('http')
      ? finalHref
      : 'https://www.antupload.com' + finalHref

    return {
      url: absolute,
      headers: {
        'User-Agent': UA,
        'Referer': url,
        'Cookie': cookies
      }
    }

  } catch (err) {
    console.error('resolveAntUpload error:', err.message)
    return null
  }
}

//--- SEARCH BOOKS

async function sbook(query, limit = 5) {
  const { data } = await client.get(`${BASE}/?s=${encodeURIComponent(query)}`)
  const $ = cheerio.load(data)

  const results = []

  $('article.card').each((i, el) => {
    if (i >= limit) return false

    const href = $(el).find('a.card-click-target').attr('href')
    const url = toAbsolute(href)

    const title =
      clean($(el).find('img.cover').attr('alt')) ||
      clean($(el).find('h2 a').text())

    const thumb = $(el).find('img.cover').attr('src') || ''

    const author = clean(
      $(el).find('a[href*="/autor/"]').first().text()
    )

    const genre = clean(
      $(el).find('a[href*="/genero/"]').first().text()
    ) || null

    if (!title || !url) return

    results.push({ title, author, thumb, url, genre })
  })

  if (!results.length) {
    throw new Error(`Sin resultados para: ${query}`)
  }

  return results
}


//-- BOOK INFO + DOWNLOAD

async function bookdl(url) {
  const { data } = await client.get(url)
  const $ = cheerio.load(data)

  const title = clean($('#title').text())

  const author = clean(
    $('#autor').text().replace(/^Autor:\s*/i, '')
  )

  const genre = clean(
    $('a[href*="/genero/"]').first().text().replace(/^Genero:\s*/i, '')
  ) || null

  const year = clean(
    $('#publicado').text().replace(/^Publicado:\s*/i, '')
  ) || null

  let description = ''

  $('#book .description, #content .description, .book .description')
    .each((_, el) => {
      const txt = clean($(el).text())
      if (txt.length > description.length) description = txt
    })

  if (!description) {
    description = clean(
      $('meta[property="og:description"]').attr('content')
    )
  }

  const thumb =
    $('meta[property="og:image"]').attr('content') ||
    $('img.cover').attr('src') ||
    ''

  const getAntUploadLink = (href) => {
    if (!href) return null

    const dMatch = href.match(/[?&]d=([^&]+)/)

    if (dMatch?.[1]) {
      try {
        const decoded = Buffer.from(dMatch[1], 'base64').toString('utf-8')
        return 'https://www.antupload.com/file/' + decoded
      } catch {}
    }

    return toAbsolute(href)
  }

  let epubLink = null
  let pdfLink = null

  $('a').each((_, el) => {
    const href = $(el).attr('href') || ''

    if (!href.includes('download.php')) return

    const tVal = href.match(/[?&]t=(\d+)/)?.[1]

    if (tVal === '1') epubLink = getAntUploadLink(href)
    if (tVal === '2') pdfLink = getAntUploadLink(href)
  })

  if (!epubLink) {
    epubLink = getAntUploadLink($('#download1').attr('href'))
  }

  if (!pdfLink) {
    pdfLink = getAntUploadLink($('#download2').attr('href'))
  }

  /* ===== resolve ===== */

  const [finalEpub, finalPdf] = await Promise.all([
    safe(() => resolveAntUpload(epubLink)),
    safe(() => resolveAntUpload(pdfLink))
  ])

  return {
    title,
    author,
    description: clean(description).slice(0, 1000),
    genre,
    year,
    thumb,
    url,
    download: {
      epub: finalEpub,
      pdf: finalPdf
    }
  }
}

/* ========================= */

module.exports = {
  sbook,
  bookdl
}